   for(const {member,context} of roles){if(added>=3)break;try{const ownCollections=Core.collectionsForActor(w,member.actorId).map(item=>({id:item.id,name:item.name,description:item.description})),canPost=Core.canRolePost(member),marketCandidates=canPost?roleDeliveredPurchases(w,member,context.character):[];const task=`角色可用权限：${JSON.stringify({allowPosts:canPost,allowComments:member.permissions?.allowComments!==false,allowReplyCharacters:member.permissions?.allowReplyCharacters!==false,allowReplyNpcs:member.permissions?.allowReplyNpcs!==false,allowReplyPersonas:member.permissions?.allowReplyPersonas!==false})}\n近期公开帖子与讨论：${JSON.stringify(recent())}\n该角色自己的私人合集：${JSON.stringify(ownCollections)}\n${canPost?`该角色本人已送达的购物记录（仅在角色自然愿意公开时使用）：${JSON.stringify(marketCandidates)}。若决定公开某件商品，在帖子数据的 marketItemId 填对应 id；否则留空。不得透露价格、订单编号、地址、钱包或私人附言。`:''}\n生成 0 至 ${3-added} 条该角色自己的论坛动态；不要模拟其他账号，可以不发言。帖子只能加入该角色自己的合集；可以自然新建自己的合集。若发评论，提供符合权限的 postId，可选 parentId。${canPost?'可发帖或评论。':'仅可评论。'}${member.permissions?.allowComments===false?'不可评论。':''}\n只输出 JSON：{"posts":[{"content":"正文","topics":["话题"],"marketItemId":"自愿公开的记录 id 或空字符串","collectionId":"自己的合集 id 或空字符串","collectionName":"需要新建时填写，否则空字符串","collectionDescription":"可选简介"}],"comments":[{"postId":"帖子 ID","parentId":"可选评论 ID","content":"评论"}]}.`;const result=await requestAI(rolePrompt(w,{member,...context},task));for(const item of Array.isArray(result.posts)?result.posts.slice(0,3):[]){if(added>=3||!canPost)break;if(addPost(member.actorId,'character',item,member,context.character)){member.lastActivityAt=Date.now();added++}}for(const item of Array.isArray(result.comments)?result.comments.slice(0,3):[]){if(added>=3||member.permissions?.allowComments===false)break;if(addComment(member.actorId,'character',item,member)){member.lastActivityAt=Date.now();added++}}}catch{failures++}}
   w.lastAiUpdateAt=Date.now();w.events.push({id:uid(),kind:'ai-update',createdAt:w.lastAiUpdateAt,count:added});runtime.save();noticeText=added?`社区新增 ${added} 条动态`:failures?'部分论坛动态生成失败，可重试':'本次没有适合发布的新动态';view.filter='latest';view.limit=18;render();
