 const back=()=>{if(view.page==='feed')return false;if(view.page==='collection'){go('feed');return true}if(view.page==='detail'&&view.returnPage==='collection'){go('collection',{collectionId:view.returnCollectionId});return true}if(view.page==='world-edit'||view.page==='world-add'){go('profile',{actorId:personaActor(),profileManagerTab:'world'});return true}if(view.page==='edit-post'){go('detail',{postId:view.postId});return true}if(view.page==='profile-edit'){go('profile',{actorId:personaActor()});return true}go('feed');return true};
